"""Standalone review of every future-activity forecast, with no external scripts."""
import argparse,json
from pathlib import Path
import numpy as np
from metrics import pinball
ROOT=Path(__file__).resolve().parents[2]
def main():
    p=argparse.ArgumentParser();p.add_argument('--out',type=Path,default=ROOT/'reports/transformer_stage2_20261012');a=p.parse_args();out=a.out;z=np.load(out/'dataset.npz');run=json.loads((out/'remote/run.json').read_text());models={};scores={};factor=z['target_scale'][None,:,:,None]*z['test_anchor_price'][:,None,None,None]
    for name in list(run['families'])+list(run['baselines']):
        q=np.load(out/'remote'/f'{name}_test.npz')['prediction'];models[name]=(q*factor).tolist();scores[name]=pinball(q,z['test_y']).mean((1,2,3)).tolist()
    data=dict(selected=run['selected_family'],dates=[str(np.datetime64(int(z['start_minute']+i),'m')) for i in z['test_origins']],models=models,scores=scores,actual=(z['test_relative']*z['test_anchor_price'][:,None,None]).tolist())
    page=r'''<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Этап 2 — будущая активность</title><style>body{font:16px system-ui;background:#f5f6f8;color:#182235;max-width:1120px;margin:28px auto;padding:0 18px}h1{font-size:27px}.card{background:white;padding:18px;border-radius:12px;margin:16px 0}.muted{color:#526174;line-height:1.5}button,select{padding:8px;margin-right:10px;border:1px solid #bec6d3;border-radius:6px;background:white;color:#182235}input{width:100%}table{border-collapse:collapse;width:100%;font-size:14px}th,td{padding:10px;border-bottom:1px solid #e5e9ee;text-align:right}th:first-child,td:first-child{text-align:left}.charts{display:grid;grid-template-columns:1fr 1fr;gap:20px}svg{width:100%;height:90px}.ok{color:#2a7c50}.bad{color:#a22e37}@media(max-width:750px){.charts{grid-template-columns:1fr}table{font-size:12px}th,td{padding:6px}}</style>
<h1>Этап 2: будущая активность на 60 и 120 минут</h1><p class="muted">Прогноз построен только по прошлым угловым векторам. Правильный ответ находится после момента прогноза. Размах — будущий max High − min Low. Суммарные колебания — сумма абсолютных минутных изменений Close, включая первое изменение от текущего Close. Это длина пути, а не направление или конечное изменение цены.</p>
<div class="card"><select id="model"><option value="static">Transformer</option><option value="hyper">Transformer + гиперсеть</option><option value="hyper_fixed">Фиксированное условие гиперсети</option><option value="train_distribution">Историческое распределение</option><option value="past_activity">Прогноз по недавней активности</option></select><button id="prev">←</button><button id="next">→</button><button id="worst">Худший пример</button><button id="median">Средний по ошибке</button><p id="date"></p><input id="sample" type="range" min="0" step="1"><p id="score"></p></div>
<div class="card"><div id="charts" class="charts"></div><p class="muted">Синяя полоса — q10–q90, точка — медиана прогноза, чёрная черта — фактическая будущая активность. Диапазоны не гарантируют 80% покрытия: фактическое покрытие и смещение приведены в отчёте.</p></div>
<div class="card"><table><thead><tr><th>Величина</th><th>q10, $</th><th>Медиана, $</th><th>q90, $</th><th>Факт, $</th><th>Попал в диапазон</th></tr></thead><tbody id="rows"></tbody></table></div>
<script id="data" type="application/json">DATA_JSON</script><script>
const d=JSON.parse(document.getElementById('data').textContent),slider=document.getElementById('sample'),model=document.getElementById('model');slider.max=d.dates.length-1;model.value=d.selected;const names=['Размах следующих 60 минут','Суммарные колебания следующих 60 минут','Размах следующих 120 минут','Суммарные колебания следующих 120 минут'];
function render(){const i=Number(slider.value),key=model.value,p=d.models[key][i],actual=d.actual[i];document.getElementById('date').textContent=`Момент прогноза ${d.dates[i]} · пример ${i+1} / ${d.dates.length}`;document.getElementById('score').textContent=`Средний нормированный quantile loss этого примера: ${d.scores[key][i].toFixed(4)}`;const charts=document.getElementById('charts'),rows=document.getElementById('rows');charts.replaceChildren();rows.replaceChildren();for(let k=0;k<4;k++){const h=Math.floor(k/2),m=k%2,q=p[h][m],v=actual[h][m],max=Math.max(q[2],v)*1.15||1,X=x=>25+400*x/max,inside=v>=q[0]&&v<=q[2];const div=document.createElement('div'),title=document.createElement('strong');title.textContent=names[k];div.append(title);const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 460 90');svg.innerHTML=`<line x1="25" y1="48" x2="425" y2="48" stroke="#b7c0ce"/><rect x="${X(q[0])}" y="33" width="${X(q[2])-X(q[0])}" height="30" fill="#3266ad" opacity=".25"/><circle cx="${X(q[1])}" cy="48" r="5" fill="#3266ad"/><line x1="${X(v)}" y1="25" x2="${X(v)}" y2="71" stroke="#111" stroke-width="2"/><text x="25" y="87" font-size="12" fill="#526174">$0</text><text x="385" y="87" font-size="12" fill="#526174">$${max.toFixed(1)}</text>`;div.append(svg);charts.append(div);const tr=document.createElement('tr');for(const value of [names[k],q[0].toFixed(2),q[1].toFixed(2),q[2].toFixed(2),v.toFixed(2),inside?'Да':'Нет']){const td=document.createElement('td');td.textContent=value;tr.append(td)}tr.lastChild.className=inside?'ok':'bad';rows.append(tr)}}
slider.addEventListener('input',render);model.addEventListener('change',render);document.getElementById('prev').onclick=()=>{slider.value=Math.max(0,Number(slider.value)-1);render()};document.getElementById('next').onclick=()=>{slider.value=Math.min(d.dates.length-1,Number(slider.value)+1);render()};document.getElementById('worst').onclick=()=>{const v=d.scores[model.value];slider.value=v.indexOf(Math.max(...v));render()};document.getElementById('median').onclick=()=>{const v=d.scores[model.value].map((x,i)=>[x,i]).sort((a,b)=>a[0]-b[0]);slider.value=v[Math.floor(v.length/2)][1];render()};render();
</script></html>'''
    (out/'review.html').write_text(page.replace('DATA_JSON',json.dumps(data,separators=(',',':'))));print('Review',out/'review.html','samples',len(data['dates']))
if __name__=='__main__':main()
